# Updated files:

## worker.js

将 Worker 升级为 API 代理服务器。它会拦截 `/api/chat` 请求，利用后台的 `API_KEY` 调用 Google Gemini，其余请求则正常返回网页静态资源。

```javascript
export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // 1. 拦截 API 请求 (处理聊天逻辑)
    if (url.pathname === '/api/chat' && request.method === 'POST') {
      // 安全检查：确认后台是否配置了 Key
      if (!env.API_KEY) {
        return new Response(JSON.stringify({ error: "Server Configuration Error: API_KEY is missing in Cloudflare Settings." }), {
          status: 500,
          headers: { 'Content-Type': 'application/json' }
        });
      }

      try {
        const { contents, systemInstruction } = await request.json();

        // 调用 Google Gemini REST API
        // 使用 v1beta 接口
        const geminiUrl = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${env.API_KEY}`;

        const payload = {
          contents: contents,
          systemInstruction: systemInstruction ? { parts: [{ text: systemInstruction }] } : undefined,
          generationConfig: {
            temperature: 0.7
          }
        };

        const response = await fetch(geminiUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });

        const data = await response.json();

        // 将 Google 的原始返回转发给前端
        return new Response(JSON.stringify(data), {
          headers: { 'Content-Type': 'application/json' }
        });

      } catch (error) {
        return new Response(JSON.stringify({ error: error.message }), {
          status: 500,
          headers: { 'Content-Type': 'application/json' }
        });
      }
    }

    // 2. 如果不是 API 请求，则返回前端静态资源 (HTML/CSS/JS)
    // env.ASSETS 是 Cloudflare 自动提供的绑定，指向 dist 目录
    return env.ASSETS.fetch(request);
  },
};
```

