export const sendMessageToGemini = async (history: ChatMessage[], newMessage: string, language: 'zh' | 'en' = 'zh'): Promise<string> => {
  try {
    // 构建 Gemini API 需要的消息格式
    const langInstruction = language === 'zh' ? "请用中文回答。" : "Please answer in English.";

    const contents = [
      ...history.map(msg => ({
        role: msg.role,
        parts: [{ text: msg.text }]
      })),
      { role: 'user', parts: [{ text: newMessage + `\n\n(System Note: ${langInstruction})` }] }
    ];

    // 发送请求到我们自己的后端 Worker
    const response = await fetch('/api/chat', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        contents: contents,
        systemInstruction: RESUME_CONTEXT
      })
    });

    if (!response.ok) {
      const errData = await response.json().catch(() => ({}));
      console.error("Backend API Error:", errData);
      throw new Error(`Server responded with ${response.status}`);
    }

    const data = await response.json();

    // 解析 Gemini 的响应结构
    const text = data.candidates?.[0]?.content?.parts?.[0]?.text;

    if (!text) {
      throw new Error("No content in response");
    }

    return text;

  } catch (error) {
    console.error("Chat Service Error:", error);
    return language === 'zh' 
      ? "连接助手时出现问题，请稍后再试。" 
      : "Connection issue. Please try again later.";
  }
};
