    const langInstruction = language === 'zh' ? "请用中文回答。" : "Please answer in English.";

    const payload = {
      contents: [
        ...history.map(msg => ({
          role: msg.role,
          parts: [{ text: msg.text }]
        })),
        { role: 'user', parts: [{ text: newMessage + `\n\n(System Note: ${langInstruction})` }] }
      ],
      systemInstruction: RESUME_CONTEXT
    };

