Add OPTIONS handler for CORS and ensure POST requests are correctly intercepted before falling back to assets.

```javascript
export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // 处理 API 请求
    if (url.pathname === '/api/chat') {
      // 处理预检请求 (CORS Preflight) - 虽然同源通常不需要，但加上能避免某些 405 问题
      if (request.method === 'OPTIONS') {
        return new Response(null, {
          headers: {
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Methods': 'POST, OPTIONS',
            'Access-Control-Allow-Headers': 'Content-Type',
          },
        });
      }

      // 处理 POST 请求
      if (request.method === 'POST') {
        // 安全检查
        if (!env.API_KEY) {
          return new Response(JSON.stringify({ 
            error: "Config Error: API_KEY missing in Cloudflare Variables." 
          }), {
            status: 500,
            headers: { 'Content-Type': 'application/json' }
          });
        }

        try {
          const reqBody = await request.json();
          const { contents, systemInstruction } = reqBody;

          // 使用 gemini-1.5-flash
          const geminiUrl = `https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${env.API_KEY}`;

          const payload = {
            contents: contents,
            systemInstruction: systemInstruction ? { parts: [{ text: systemInstruction }] } : undefined,
            generationConfig: {
              temperature: 0.7
            }
          };

          const geminiResponse = await fetch(geminiUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          });

          if (!geminiResponse.ok) {
            const errorText = await geminiResponse.text();
            return new Response(JSON.stringify({ 
              error: `Gemini API Error (${geminiResponse.status})`, 
              details: errorText 
            }), {
              status: geminiResponse.status,
              headers: { 'Content-Type': 'application/json' }
            });
          }

          const data = await geminiResponse.json();
          return new Response(JSON.stringify(data), {
            headers: { 'Content-Type': 'application/json' }
          });

        } catch (error) {
          return new Response(JSON.stringify({ error: `Worker Exception: ${error.message}` }), {
            status: 500,
            headers: { 'Content-Type': 'application/json' }
          });
        }
      }

      // 如果是 /api/chat 但不是 POST/OPTIONS，返回 405 Method Not Allowed
      return new Response("Method Not Allowed", { status: 405 });
    }

    // 所有非 API 请求，回退到静态资源
    return env.ASSETS.fetch(request);
  },
};
