// 内部函数：直接调用 Google API (客户端模式)
const callGoogleDirectly = async (history: ChatMessage[], newMessage: string, apiKey: string): Promise<string> => {
  const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${apiKey}`;

  const payload = {
    contents: [
      ...history.map(msg => ({
        role: msg.role,
        parts: [{ text: msg.text }]
      })),
      { role: 'user', parts: [{ text: newMessage }] }
    ],
    systemInstruction: { parts: [{ text: RESUME_CONTEXT }] },
    generationConfig: { temperature: 0.7 }
  };

  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });

  if (!response.ok) {
    const errText = await response.text();
    throw new Error(`Direct API Error (${response.status}): ${errText}`);
  }

  const data = await response.json();
  return data.candidates?.[0]?.content?.parts?.[0]?.text || "";
};

export const sendMessageToGemini = async (history: ChatMessage[], newMessage: string, language: 'zh' | 'en' = 'zh'): Promise<string> => {
  const langInstruction = language === 'zh' ? "请用中文回答。" : "Please answer in English.";
  const finalMessage = newMessage + `\n\n(System Note: ${langInstruction})`;

  // 1. 尝试后端代理模式 (Vercel/Cloudflare)
  try {
    const payload = {
      contents: [
        ...history.map(msg => ({ role: msg.role, parts: [{ text: msg.text }] })),
        { role: 'user', parts: [{ text: finalMessage }] }
      ],
      systemInstruction: RESUME_CONTEXT
    };

    const response = await fetch('/api/chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });

    // 如果后端返回 404 (未找到) 或 405 (方法不允许)，说明没有后端服务，抛出特定错误以触发降级
    if (response.status === 404 || response.status === 405) {
      throw new Error("BACKEND_NOT_FOUND");
    }

    if (!response.ok) {
      const errorData = await response.json().catch(() => null);
      throw new Error(errorData?.error || `Server Error (${response.status})`);
    }

    const data = await response.json();
    const text = data.candidates?.[0]?.content?.parts?.[0]?.text;
    if (!text) throw new Error("Empty response from server");
    return text;

  } catch (error: any) {
    console.warn("Backend attempt failed:", error.message);

    // 2. 降级到客户端直连模式 (EdgeOne Static / Localhost)
    // 只有当错误是 "后端不存在" 且我们有 API Key 时才尝试
    const apiKey = process.env.API_KEY;

    if ((error.message === "BACKEND_NOT_FOUND" || error.message.includes("Failed to fetch")) && apiKey) {
      try {
        console.info("Switching to Client-Side Direct API call...");
        const text = await callGoogleDirectly(history, finalMessage, apiKey);
        return text;
      } catch (directError: any) {
        console.error("Direct API failed:", directError);
        return `[系统提示] 连接失败。后端和直连模式均无法访问 (${directError.message})。请检查网络或 API Key。`;
      }
    }

    return `[系统提示] 发生错误: ${error.message}`;
  }
};
